'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let index = 0;
const n = input[index++];
const dice = [];

for (let i = 0; i < n; i++) {
  const faces = input.slice(index, index + 6);
  index += 6;

  const opposite = Array(7);
  opposite[faces[0]] = faces[5];
  opposite[faces[5]] = faces[0];
  opposite[faces[1]] = faces[3];
  opposite[faces[3]] = faces[1];
  opposite[faces[2]] = faces[4];
  opposite[faces[4]] = faces[2];

  dice.push({ faces, opposite });
}

let answer = 0;

for (let start = 1; start <= 6; start++) {
  let bottom = start;
  let sum = 0;

  for (const die of dice) {
    const top = die.opposite[bottom];
    let sideMax = 0;

    for (const value of die.faces) {
      if (value !== bottom && value !== top) {
        sideMax = Math.max(sideMax, value);
      }
    }

    sum += sideMax;
    bottom = top;
  }

  answer = Math.max(answer, sum);
}

console.log(answer);
